body {
    font-family: sans-serif;
    margin: 0;
    padding: 20px;
    background-color: #f4f4f4;
}

#container {
    display: flex;
    flex-direction: row;
    height: 90vh;
    gap: 20px;
}

#chart-container {
    flex: 2;
    background: white;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

#table-container {
    flex: 1;
    background: white;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
    overflow: auto;
}

h2 {
    margin-top: 0;
    padding: 10px 20px;
    border-bottom: 1px solid #eee;
    background-color: #fafafa;
}

/* Bubble Chart Styles */
circle {
    stroke: #fff;
    stroke-width: 1.5px;
    cursor: pointer;
    transition: stroke-width 0.2s, stroke 0.2s;
}

circle:hover {
    stroke: #333;
    stroke-width: 2px;
}

circle.highlighted {
    stroke: #000;
    stroke-width: 3px;
}

text.label {
    font-size: 10px;
    font-family: sans-serif;
    text-anchor: middle;
    pointer-events: none;
    fill: #333;
    font-weight: bold;
}

/* Tooltip */
.tooltip {
    position: absolute;
    padding: 10px;
    background: rgba(0, 0, 0, 0.85);
    color: white;
    border-radius: 4px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
    font-size: 12px;
    z-index: 10;
    max-width: 200px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
}

.tooltip.visible {
    opacity: 1;
}

/* Table Styles */
table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    padding: 10px;
    text-align: left;
    border-bottom: 1px solid #eee;
    font-size: 13px;
}

th {
    background-color: #fafafa;
    position: sticky;
    top: 0;
    z-index: 1;
    font-weight: 600;
    color: #555;
}

tr:hover {
    background-color: #f9f9f9;
}

tr.highlighted {
    background-color: #ffe0b2; /* Light orange highlight */
}

/* Legend */
.legend {
    font-size: 12px;
    font-family: sans-serif;
}
.legend-item {
    cursor: pointer;
}

