// Main visualization function
async function initVisualization() {
    // 1. Load Data
    const data = await d3.csv("data/stock-descriptions.csv");

    // 2. Process Data
    // Convert marketCap to number, handle ETFs (missing cap)
    data.forEach(d => {
        d.marketCapRaw = d.marketCap ? +d.marketCap : 0;
        d.isETF = d.sector === "ETF" || !d.marketCap; // Assuming empty cap means ETF or similar
        // If sector is missing/empty, label it 'Unknown' or keep as is? 
        // Based on file check, ETFs have sector='ETF'.
    });

    // Sort by market cap descending for better circle stacking (large ones first usually, or small on top? large first is standard for drawing order so small ones aren't hidden? actually small on top is better. sort ascending size.)
    data.sort((a, b) => b.marketCapRaw - a.marketCapRaw);

    // 3. Setup Dimensions & SVG
    const container = document.getElementById("chart");
    const width = container.clientWidth || 800;
    const height = container.clientHeight || 600; // Use fixed height if container is 0 initially? 
    // Container in CSS is flex column inside chart-container which has height. 
    // Let's rely on getBoundingClientRect or fixed aspect ratio.
    const rect = container.getBoundingClientRect();
    const svgWidth = rect.width || 800;
    const svgHeight = 600; // Fixed height for simulation stability

    const svg = d3.select("#chart")
        .append("svg")
        .attr("width", "100%")
        .attr("height", "100%")
        .attr("viewBox", `0 0 ${svgWidth} ${svgHeight}`)
        .style("display", "block");

    // 4. Scales
    // Size Scale
    const maxCap = d3.max(data, d => d.marketCapRaw);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxCap])
        .range([10, 65]); // Min radius 10, max 65

    // Color Scale (Sector)
    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    // Cluster Centers (ForceX/Y targets)
    // Arrange sectors in a grid or circle. 
    // We have ~11 sectors + ETF. ~12 groups.
    // 3 rows x 4 cols grid.
    const cols = 4;
    const rows = 3; // 4x3 = 12
    const paddingX = svgWidth / (cols + 1);
    const paddingY = svgHeight / (rows + 1);

    const clusterCenters = {};
    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        clusterCenters[sector] = { 
            x: (col + 1) * paddingX, 
            y: (row + 1) * paddingY 
        };
    });

    // 5. Force Simulation
    const simulation = d3.forceSimulation(data)
        .force("x", d3.forceX(d => clusterCenters[d.sector] ? clusterCenters[d.sector].x : svgWidth/2).strength(0.15))
        .force("y", d3.forceY(d => clusterCenters[d.sector] ? clusterCenters[d.sector].y : svgHeight/2).strength(0.15))
        .force("collide", d3.forceCollide(d => (d.isETF ? 20 : radiusScale(d.marketCapRaw)) + 2).strength(0.8)) // +2 padding
        .force("charge", d3.forceManyBody().strength(-10)); // Slight repulsion

    // 6. Render Elements

    // Group for bubbles to keep z-index correct (text on top? usually text inside group with circle)
    const node = svg.append("g")
        .selectAll("g")
        .data(data)
        .join("g")
        .attr("class", "node")
        .style("cursor", "pointer")
        .call(d3.drag() // Add drag behavior for better interactivity
            .on("start", dragstarted)
            .on("drag", dragged)
            .on("end", dragended));

    const circles = node.append("circle")
        .attr("r", d => d.isETF ? 20 : radiusScale(d.marketCapRaw)) // Fixed size for ETFs
        .attr("fill", d => colorScale(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5);

    const labels = node.append("text")
        .attr("class", "label")
        .attr("dy", "0.35em")
        .text(d => d.ticker)
        .style("font-size", d => {
            const r = d.isETF ? 20 : radiusScale(d.marketCapRaw);
            return Math.min(12, r / 1.5) + "px"; // Scale text slightly, max 12px
        });

    // 7. Tooltip Logic
    const tooltip = d3.select("#tooltip");

    node.on("mouseover", (event, d) => {
        // "ETF entries have no marketCap, country, or website data, so do not show tooltip for them"
        if (d.isETF) return;

        tooltip.classed("visible", true)
            .html(`
                <strong>${d.ticker}</strong><br/>
                ${d['full name']}<br/>
                <span style="color: #aaa">${d.sector}</span>
            `);
    })
    .on("mousemove", (event) => {
        tooltip.style("left", (event.pageX + 15) + "px")
               .style("top", (event.pageY - 10) + "px");
    })
    .on("mouseout", () => {
        tooltip.classed("visible", false);
    });

    // 8. Interaction (Click)
    node.on("click", (event, d) => {
        highlight(d.ticker);
    });

    // 9. Simulation Tick
    simulation.on("tick", () => {
        node.attr("transform", d => `translate(${d.x},${d.y})`);
    });

    // 10. Legends
    // Simple legend at top or bottom? Or distinct labels near clusters?
    // Let's add a legend container in SVG.
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", "translate(20, 20)");

    sectors.forEach((sector, i) => {
        const g = legend.append("g")
            .attr("transform", `translate(0, ${i * 20})`);

        g.append("rect")
            .attr("width", 12)
            .attr("height", 12)
            .attr("fill", colorScale(sector));

        g.append("text")
            .attr("x", 20)
            .attr("y", 10)
            .text(sector);
    });

    // 11. Populate Table
    const tableBody = d3.select("#stock-table tbody");

    // Format market cap helper
    const formatCap = (val) => {
        if (!val) return "N/A";
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val;
    };

    const rows = tableBody.selectAll("tr")
        .data(data)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .on("click", (event, d) => {
            highlight(d.ticker);
        });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d['full name']);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => d.isETF ? "N/A" : formatCap(d.marketCapRaw));

    // 12. Highlight Logic
    function highlight(ticker) {
        // Reset
        d3.selectAll("circle").classed("highlighted", false);
        d3.selectAll("tr").classed("highlighted", false);

        // Highlight Bubble
        const targetNode = node.filter(d => d.ticker === ticker);
        targetNode.select("circle").classed("highlighted", true);

        // Highlight Row
        const targetRow = rows.filter(d => d.ticker === ticker);
        targetRow.classed("highlighted", true);

        // Scroll row into view
        const rowNode = targetRow.node();
        if (rowNode) {
            rowNode.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }

    // Drag functions
    function dragstarted(event, d) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
    }

    function dragged(event, d) {
        d.fx = event.x;
        d.fy = event.y;
    }

    function dragended(event, d) {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
    }
}

// Start
initVisualization();

